def func1(data):
    result = 0
    output = []
    info = {}

    # Handle list input
    if isinstance(data, list):
        for i, item in enumerate(data):
            if isinstance(item, int) or isinstance(item, float):
                if item % 2 == 0:
                    result += item
                else:
                    result += item * 2
                output.append(result)
            elif isinstance(item, str):
                cleaned = ''.join(ch.lower() for ch in item if ch.isalnum())
                output.append(cleaned[::-1])
            elif isinstance(item, dict):
                for k, v in item.items():
                    info[str(k)] = info.get(str(k), 0) + (v if isinstance(v, (int,float)) else 1)
        return output if output else info

    # Handle integer input
    elif isinstance(data, int):
        a, b = 0, 1
        seq = []
        for _ in range(max(0, data)):
            seq.append(a)
            a, b = b, a + b
        return seq

    # Handle string input
    elif isinstance(data, str):
        freq = {}
        for ch in data:
            if ch.isalpha():
                freq[ch.lower()] = freq.get(ch.lower(), 0) + 1
        return dict(sorted(freq.items(), key=lambda x: (-x[1], x[0])))

    # Handle dictionary input
    elif isinstance(data, dict):
        total = 0
        for k, v in data.items():
            if isinstance(v, (int,float)):
                total += v
            elif isinstance(v, str):
                total += len(v)
        info["sum"] = total
        info["keys"] = list(data.keys())
        return info

    # Handle float input
    elif isinstance(data, float):
        n = int(abs(data))
        factors = []
        for i in range(1, n+1):
            if n % i == 0:
                factors.append(i)
        return factors

    return None

def func1(data):
    result = []
    try:
        if isinstance(data, dict):
            visited = set()
            for k, v in data.items():
                if isinstance(v, list):
                    for node in v:
                        if node not in visited:
                            visited.add(node)
                            result.append((k, node))
                elif isinstance(v, (int, float)):
                    if v % 2 == 0:
                        result.append((k, v))
                    else:
                        result.append((k, v * 3))
                elif isinstance(v, str):
                    parts = [p for p in v.split() if p]
                    result.extend(parts)
            return result
        elif isinstance(data, list):
            stack = []
            for item in data:
                if isinstance(item, int):
                    if item > 0:
                        stack.append(item)
                    else:
                        if stack:
                            stack.pop()
                elif isinstance(item, str):
                    stack.append(len(item))
                elif isinstance(item, float):
                    stack.append(round(item))
            return stack
        elif isinstance(data, str):
            words = data.split()
            freq = {}
            for w in words:
                key = w.lower()
                freq[key] = freq.get(key, 0) + 1
            filtered = [k for k, v in freq.items() if v >= 1]
            return filtered
        else:
            return []
    except Exception as e:
        return ["error", str(e)]

